using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<vector<int>> children(n);
    for (int v = 1; v < n; v++) {
        int p;
        cin >> p;
        children[p - 1].push_back(v);
    }
    // Iterative preorder; processing it in reverse handles every child before its parent.
    vector<int> order, st = {0};
    order.reserve(n);
    while (!st.empty()) {
        int v = st.back();
        st.pop_back();
        order.push_back(v);
        for (int c : children[v]) st.push_back(c);
    }
    vector<long long> size(n, 1);
    long long balanced = 0;
    for (int k = n - 1; k >= 0; k--) {
        int v = order[k];
        bool ok = true;
        for (int c : children[v]) {
            size[v] += size[c];
            if (size[c] != size[children[v][0]]) ok = false;
        }
        balanced += ok;
    }
    cout << balanced << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        int[] parent = new int[n], head = new int[n], next = new int[n];
        Arrays.fill(head, -1);
        for (int v = 1; v < n; v++) parent[v] = nextInt() - 1;
        // Linked child lists, built in reverse so each list keeps input order.
        for (int v = n - 1; v >= 1; v--) {
            next[v] = head[parent[v]];
            head[parent[v]] = v;
        }
        int[] order = new int[n], stack = new int[n];
        int top = 0, cnt = 0;
        stack[top++] = 0;
        while (top > 0) {
            int v = stack[--top];
            order[cnt++] = v;
            for (int c = head[v]; c != -1; c = next[c]) stack[top++] = c;
        }
        long[] size = new long[n];
        Arrays.fill(size, 1);
        long balanced = 0;
        for (int k = n - 1; k >= 0; k--) {
            int v = order[k];
            boolean ok = true;
            long expected = -1;
            for (int c = head[v]; c != -1; c = next[c]) {
                size[v] += size[c];
                if (expected == -1) expected = size[c];
                else if (size[c] != expected) ok = false;
            }
            if (ok) balanced++;
        }
        System.out.println(balanced);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := nextInt()
	children := make([][]int32, n)
	for v := 1; v < n; v++ {
		p := nextInt() - 1
		children[p] = append(children[p], int32(v))
	}
	order := make([]int32, 0, n)
	stack := []int32{0}
	for len(stack) > 0 {
		v := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		order = append(order, v)
		stack = append(stack, children[v]...)
	}
	size := make([]int64, n)
	balanced := 0
	for k := n - 1; k >= 0; k-- {
		v := order[k]
		size[v] = 1
		ok := true
		for _, c := range children[v] {
			size[v] += size[c]
			if size[c] != size[children[v][0]] {
				ok = false
			}
		}
		if ok {
			balanced++
		}
	}
	fmt.Println(balanced)
}
